			function getTrpr(){
			    util.Submit.send(app, "subTrpr", function(pbSuccess) {
			        if (pbSuccess) {
			            var dsCaseTrprList = app.lookup("dsCaseTrprList");
			            if(dsCaseTrprList.getRowCount() > 0){
			                app.lookup("dmResrceNo").setValue("RESRCE_NO", dsCaseTrprList.getValue(0, "RESRCE_NO"));
			                app.lookup("dmResrceNo").setValue("RESRCE_NM", dsCaseTrprList.getValue(0, "RESRCE_NM"));
			            }
			            util.Control.redraw(app, "grpCaseTrprList");
			        }
			    });
			}

			/*
			 * "닫기" 버튼(btnClose)에서 click 이벤트 발생 시 호출.
			 * 사용자가 컨트롤을 클릭할 때 발생하는 이벤트.
			 */
			function onBtnCloseClick(e){
			     /** @type cpr.controls.MDIFolder */
			    var mdiCn = app.getRootAppInstance().lookup("mdiCn");
			    var appId = app.id;
			    if (appId.indexOf("$") > -1) {
			        appId = appId.substring(0, appId.lastIndexOf("$"));
			    }
			    var vcFindItem = mdiCn.findItemWithAppID(appId);
			    mdiCn.close(vcFindItem);
			}

