			// validation 체크
			function chkVal(){
			    var dmUnRegCase = app.lookup("dmUnRegCase");
			    if(ValueUtil.isNull(dmUnRegCase.getValue("SPRT_BGNG_YMD")) || ValueUtil.isNull(dmUnRegCase.getValue("SPRT_END_YMD"))){
			        util.Msg.alert(app, "지원기간을 입력해 주세요.");
			        return false;
			    }
			    
			    if(!ValueUtil.isNull(dmUnRegCase.getValue("SPRT_BGNG_HR")) || !ValueUtil.isNull(dmUnRegCase.getValue("SPRT_END_HR"))){
			        var sprtBgngHr = dmUnRegCase.getValue("SPRT_BGNG_HR");
			        var sprtEndHr = dmUnRegCase.getValue("SPRT_END_HR");
			        var bgngHH = sprtBgngHr.substr(0,2);
			        var bgngMI = sprtBgngHr.substr(2,2);
			        var endHH = sprtEndHr.substr(0,2);
			        var endMI = sprtEndHr.substr(2,2);
			        if(ValueUtil.isNull(bgngHH) || ValueUtil.isNull(bgngMI) || ValueUtil.isNull(endHH) || ValueUtil.isNull(endMI)){
			            util.Msg.alert(app, "지원시간의 시간형식이 맞지 않습니다.");
			            return false;
			        }
			        if(bgngHH >= 24 || bgngMI >= 60 || endHH >= 24 || endMI >= 60){
			            util.Msg.alert(app, "지원시간의 시간형식이 맞지 않습니다.");
			            return false;
			        }
			        if(sprtBgngHr >= sprtEndHr){
			            util.Msg.alert(app, "지원시간의 시작시간은\n종료시간 전이어야 합니다.");
			            return false;
			        }
			    }
			    
			    if(ValueUtil.isNull(dmUnRegCase.getValue("SRVC_PVSN_MTHD_SE_CD"))){
			        util.Msg.alert(app, "제공방식을 선택해 주세요.");
			        return false;
			    }
			    
			    if(ValueUtil.isNull(dmUnRegCase.getValue("SRVC_RESRCE_MLSFC_SE_CD"))){
			        util.Msg.alert(app, "서비스분류를 선택해 주세요.");
			        return false;
			    }
			    
			    if(dmUnRegCase.getValue("SRVC_RESRCE_MLSFC_SE_CD") == "0108" || dmUnRegCase.getValue("SRVC_RESRCE_MLSFC_SE_CD") == "0207"
			        || dmUnRegCase.getValue("SRVC_RESRCE_MLSFC_SE_CD") == "0304" || dmUnRegCase.getValue("SRVC_RESRCE_MLSFC_SE_CD") == "0405"
			        || dmUnRegCase.getValue("SRVC_RESRCE_MLSFC_SE_CD") == "0506" || dmUnRegCase.getValue("SRVC_RESRCE_MLSFC_SE_CD") == "0606"
			        || dmUnRegCase.getValue("SRVC_RESRCE_MLSFC_SE_CD") == "0708" || dmUnRegCase.getValue("SRVC_RESRCE_MLSFC_SE_CD") == "0806"
			        || dmUnRegCase.getValue("SRVC_RESRCE_MLSFC_SE_CD") == "0903" || dmUnRegCase.getValue("SRVC_RESRCE_MLSFC_SE_CD") == "1004"
			        || dmUnRegCase.getValue("SRVC_RESRCE_MLSFC_SE_CD") == "1110"){ // 기타(텍스트입력)
			        if(ValueUtil.isNull(dmUnRegCase.getValue("SRVC_RESRCE_ETC_NM"))){
			            util.Msg.alert(app, "서비스분류 기타내용을 선택해 주세요.");
			            return false;    
			        }
			    }
			    
			    if(ValueUtil.isNull(dmUnRegCase.getValue("SPRT_TTL_NM"))){
			        util.Msg.alert(app, "지원제목을 선택해 주세요.");
			        return false;
			    }
			    
			    var dsPic = app.lookup("dsPic");
			    for(var i = 0; i < dsPic.getRowCount(); i++){
			        if(ValueUtil.isNull(dsPic.getValue(i, "UNREGI_CASE_PIC_NO"))){
			            util.Msg.alert(app, "담당자 목록의 담당자명을 선택해 주세요.");
			            return false;
			        }
			    }
			    
			    var dsBizReg = app.lookup("dsBizReg");
			    if(dsBizReg.getRowCount() > 0){
			        for(var i = 0; i < dsBizReg.getRowCount(); i++){
			            if(ValueUtil.isNull(dsBizReg.getValue(i, "SRVC_EXCN_BIZ_NO"))){
			                util.Msg.alert(app, "사업등록 목록의 실행사업명을 선택해 주세요.");
			                return false;
			            }
			        }
			    }
			    
			    var dsExcnSrvcBizClList = app.lookup("dsExcnSrvcBizClList");
			    if(dsExcnSrvcBizClList.getRowCount() > 0){
			        for(var i = 0; i < dsExcnSrvcBizClList.getRowCount(); i++){
			            if(ValueUtil.isNull(dsExcnSrvcBizClList.getValue(i, "EXCN_SRVC_DETAIA_BIZ_NO"))){
			                util.Msg.alert(app, "실행서비스 사업분류 목록의\n실행서비스 세부사업명을 선택해 주세요.");
			                return false;
			            }
			        }
			    }
			    
			    var dsCaseTrprList = app.lookup("dsCaseTrprList");
			    if(dsCaseTrprList.getRowCount() > 0){
			        for(var i = 0; i < dsCaseTrprList.getRowCount(); i++){
			            if(ValueUtil.isNull(dsCaseTrprList.getValue(i, "TRPR_NM"))){
			                util.Msg.alert(app, "사례대상자 목록의\n사례대상자명을 선택해 주세요.");
			                return false;
			            }
			        }
			    }
			    
			    if(ValueUtil.isNull(dmUnRegCase.getValue("SPRT_CN"))){
			        util.Msg.alert(app, "지원내용을 선택해 주세요.");
			        return false;
			    }
			    
			    return true;
			}

			/*
			 * 넘버 에디터에서 value-change 이벤트 발생 시 호출.
			 * NumberEditor의 value를 변경하여 변경된 값이 저장된 후에 발생하는 이벤트.
			 */
			function onNbeValueChange(e){
			    var dmUnRegCase = app.lookup("dmUnRegCase");
			    var dmUnRegCaseCol = dmUnRegCase.getColumnNames();
			    var maleTotSum = 0;
			    var femaleTotSum = 0;
			    for(var i = 0; i < dmUnRegCaseCol.length; i++){
			        var colNm = dmUnRegCaseCol[i];
			        if(colNm.indexOf("_MALE_NOPE") > -1){
			            maleTotSum += ValueUtil.fixNumber(dmUnRegCase.getValue(colNm));
			        }
			        if(colNm.indexOf("_FEMALE_NOPE") > -1){
			            femaleTotSum += ValueUtil.fixNumber(dmUnRegCase.getValue(colNm));
			        }
			    }
			    app.lookup("maleSum").value = maleTotSum;
			    app.lookup("femaleSum").value = femaleTotSum;
			}

